n, m, q = map(int, input().split())
bit = [[0] * (m + 1) for _ in range(n + 1)]

def update(r, c, v):
    i = r
    while i <= n:
        j = c
        while j <= m:
            bit[i][j] += v
            j += j & (-j)
        i += i & (-i)

def query(r, c):
    s = 0
    i = r
    while i > 0:
        j = c
        while j > 0:
            s += bit[i][j]
            j -= j & (-j)
        i -= i & (-i)
    return s

def rect_sum(r1, c1, r2, c2):
    return query(r2, c2) - query(r1-1, c2) - query(r2, c1-1) + query(r1-1, c1-1)

for _ in range(q):
    ops = input().split()
    if ops[0] == 'U':
        r, c, v = int(ops[1]), int(ops[2]), int(ops[3])
        update(r, c, v)
    else:
        r1, c1, r2, c2 = int(ops[1]), int(ops[2]), int(ops[3]), int(ops[4])
        print(rect_sum(r1, c1, r2, c2))

