    for (int i=r;i>0;i-=i&-i)
        for (int j=c;j>0;j-=j&-j)
            s+=bit[i][j];
    return s;
}
int rect(int r1,int c1,int r2,int c2){return qry(r2,c2)-qry(r1-1,c2)-qry(r2,c1-1)+qry(r1-1,c1-1);}
